package com.lyra.studio; import android.app.Activity; import android.view.View; import android.view.WindowManager; import android.webkit.WebView; import android.webkit.WebViewClient; import com.google.appinventor.components.annotations.*; import com.google.appinventor.components.common.*; import com.google.appinventor.components.runtime.*; @DesignerComponent(version = 1, description = "Um WebView customizado que se ajusta ao teclado virtual para nao cobrir o conteudo.", category = ComponentCategory.EXTENSION, nonVisible = false, iconName = "images/extension.png") @SimpleObject(external = true) public class KeyboardAwareWebView extends AndroidViewComponent { private Activity activity; private WebView webView; public KeyboardAwareWebView(ComponentContainer container) { super(container); this.activity = container.$context(); /* Configura a janela da Activity para redimensionar o layout quando o teclado virtual abrir, evitando que cubra o WebView */ this.activity.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE); /* Instancia e configura propriedades essenciais do WebView */ this.webView = new WebView(this.activity); this.webView.getSettings().setJavaScriptEnabled(true); this.webView.getSettings().setDomStorageEnabled(true); this.webView.setWebViewClient(new WebViewClient()); /* Adiciona o componente visual ao container (tela) */ container.$add(this); } @Override public View getView() { return this.webView; } @SimpleFunction(description = "Carrega uma URL no navegador.") public void IrParaUrl(String url) { if (url != null && !url.isEmpty()) { this.webView.loadUrl(url); } } @SimpleFunction(description = "Recarrega a pagina atual.") public void Recarregar() { this.webView.reload(); } @SimpleFunction(description = "Volta para a pagina anterior.") public void Voltar() { if (this.webView.canGoBack()) { this.webView.goBack(); } } @SimpleFunction(description = "Avanca para a proxima pagina.") public void Avancar() { if (this.webView.canGoForward()) { this.webView.goForward(); } } }